INSERT INTO iam.applications (app_code, app_name, description) VALUES ('AIDAA','AI Driven Audit Assistant','Audit planning, execution and reporting') ON CONFLICT (app_code) DO NOTHING;
INSERT INTO iam.roles (app_id, role_code, role_name, description) SELECT a.app_id, v.c, v.n, v.d FROM iam.applications a, (VALUES ('AIDAA.ADMIN','AIDAA Administrator','Manages master data: units, cost standards, auditors'),('AIDAA.BOARD','Board','Approves annual audit plan'),('AIDAA.HEAD_AUDIT','Head of Audit Unit','Creates plans, issues assignments, approves reports'),('AIDAA.AUDITOR','Auditor','Base role, assignment role decides rights per audit'),('AIDAA.HR','Audit Unit HR','Manages auditor data and verifies expertise'),('AIDAA.FINANCE','Audit Unit Finance','Manages cost standards and verifies budget'),('AIDAA.GENERAL_AFFAIRS','Audit Unit General Affairs','Handles assignment logistics'),('AIDAA.AUDITEE_PIC','Auditee PIC','Responds to findings of own unit')) AS v(c,n,d) WHERE a.app_code='AIDAA' ON CONFLICT (app_id, role_code) DO NOTHING;
INSERT INTO iam.permissions (app_id, permission_code, permission_label) SELECT a.app_id, v.c, v.l FROM iam.applications a, (VALUES ('audit.unit.read','View auditable units and audit types'),('audit.unit.create','Create auditable units and audit types'),('audit.unit.update','Update auditable units and audit types'),('audit.unit.delete','Deactivate auditable units and audit types'),('audit.coststd.read','View cost standards'),('audit.coststd.create','Create cost standards'),('audit.coststd.update','Update cost standards'),('audit.coststd.delete','Deactivate cost standards'),('audit.auditor.read','View auditors'),('audit.auditor.create','Create auditors'),('audit.auditor.update','Update auditors'),('audit.auditor.delete','Deactivate auditors'),('audit.expertise.read','View expertise'),('audit.expertise.create','Submit expertise'),('audit.expertise.verify','Verify expertise'),('audit.plan.read','View audit plans'),('audit.plan.create','Create audit plans'),('audit.plan.update','Update audit plans'),('audit.plan.approve','Approve audit plans'),('audit.assignment.read','View assignments'),('audit.assignment.create','Issue assignments'),('audit.assignment.update','Update assignments'),('audit.assignment.approve_change','Approve assignment changes'),('audit.assignment.logistics','Update assignment logistics'),('audit.team.read','View audit teams'),('audit.team.manage','Manage audit teams'),('audit.team.approve_replace','Approve team replacement'),('audit.budget.read','View budget'),('audit.budget.draft','Draft budget'),('audit.budget.verify','Verify budget'),('audit.pka.read','View work programs'),('audit.pka.create','Create work programs'),('audit.pka.update','Update work programs'),('audit.pka.approve','Approve work programs'),('audit.paper.read','View working papers'),('audit.paper.create','Create working papers'),('audit.paper.update','Update working papers'),('audit.paper.review','Review working papers'),('audit.finding.read','View findings'),('audit.finding.create','Create findings'),('audit.finding.update','Update findings'),('audit.finding.approve','Approve findings'),('audit.rekomend.read','View recommendations'),('audit.rekomend.create','Create recommendations'),('audit.rekomend.update','Update recommendations'),('audit.rekomend.close','Close recommendations'),('audit.rekomend.followup','Submit follow-up'),('audit.report.read','View reports'),('audit.report.create','Create reports'),('audit.report.update','Update reports'),('audit.report.approve','Approve reports'),('audit.deviation.read','View plan deviation'),('audit.task.read','View own approval tasks')) AS v(c,l) WHERE a.app_code='AIDAA' ON CONFLICT (permission_code) DO NOTHING;
INSERT INTO iam.role_permissions (role_id, permission_id) SELECT r.role_id, p.permission_id FROM (VALUES ('AIDAA.ADMIN', ARRAY['audit.unit.read','audit.unit.create','audit.unit.update','audit.unit.delete','audit.coststd.read','audit.coststd.create','audit.coststd.update','audit.coststd.delete','audit.auditor.read','audit.auditor.create','audit.auditor.update','audit.auditor.delete','audit.expertise.read','audit.plan.read','audit.assignment.read','audit.team.read','audit.budget.read','audit.pka.read','audit.paper.read','audit.finding.read','audit.rekomend.read','audit.report.read','audit.deviation.read','audit.task.read']),('AIDAA.BOARD', ARRAY['audit.unit.read','audit.coststd.read','audit.auditor.read','audit.plan.read','audit.plan.approve','audit.assignment.read','audit.budget.read','audit.finding.read','audit.rekomend.read','audit.report.read','audit.deviation.read','audit.task.read']),('AIDAA.HEAD_AUDIT', ARRAY['audit.unit.read','audit.unit.create','audit.unit.update','audit.coststd.read','audit.auditor.read','audit.expertise.read','audit.plan.read','audit.plan.create','audit.plan.update','audit.assignment.read','audit.assignment.create','audit.assignment.update','audit.assignment.approve_change','audit.team.read','audit.team.manage','audit.team.approve_replace','audit.budget.read','audit.pka.read','audit.paper.read','audit.finding.read','audit.rekomend.read','audit.report.read','audit.report.approve','audit.deviation.read','audit.task.read']),('AIDAA.AUDITOR', ARRAY['audit.unit.read','audit.coststd.read','audit.auditor.read','audit.expertise.read','audit.expertise.create','audit.plan.read','audit.assignment.read','audit.assignment.approve_change','audit.team.read','audit.team.approve_replace','audit.budget.read','audit.budget.draft','audit.pka.read','audit.pka.create','audit.pka.update','audit.pka.approve','audit.paper.read','audit.paper.create','audit.paper.update','audit.paper.review','audit.finding.read','audit.finding.create','audit.finding.update','audit.finding.approve','audit.rekomend.read','audit.rekomend.create','audit.rekomend.update','audit.rekomend.close','audit.report.read','audit.report.create','audit.report.update','audit.deviation.read','audit.task.read']),('AIDAA.HR', ARRAY['audit.unit.read','audit.auditor.read','audit.auditor.create','audit.auditor.update','audit.auditor.delete','audit.expertise.read','audit.expertise.verify','audit.task.read']),('AIDAA.FINANCE', ARRAY['audit.unit.read','audit.coststd.read','audit.coststd.create','audit.coststd.update','audit.coststd.delete','audit.auditor.read','audit.plan.read','audit.assignment.read','audit.budget.read','audit.budget.verify','audit.deviation.read','audit.task.read']),('AIDAA.GENERAL_AFFAIRS', ARRAY['audit.unit.read','audit.coststd.read','audit.auditor.read','audit.assignment.read','audit.assignment.logistics','audit.budget.read','audit.task.read']),('AIDAA.AUDITEE_PIC', ARRAY['audit.unit.read','audit.assignment.read','audit.finding.read','audit.rekomend.read','audit.rekomend.followup','audit.report.read','audit.task.read'])) AS v(rc, pcs) CROSS JOIN LATERAL unnest(v.pcs) AS u(pc) JOIN iam.roles r ON r.role_code = v.rc JOIN iam.permissions p ON p.permission_code = u.pc ON CONFLICT (role_id, permission_id) DO NOTHING;
INSERT INTO iam.permissions (app_id, permission_code, permission_label) SELECT a.app_id, v.c, v.l FROM iam.applications a, (VALUES ('audit.library.read','View PKA and procedure library'),('audit.library.manage','Manage PKA and procedure library'),('audit.location.read','View locations'),('audit.location.create','Create locations'),('audit.location.update','Update locations'),('audit.location.delete','Deactivate locations'),('audit.costrate.read','View cost rates'),('audit.costrate.create','Create cost rates'),('audit.costrate.update','Update cost rates'),('audit.costrate.delete','Deactivate cost rates'),('audit.costrate.approve','Approve cost rates')) AS v(c,l) WHERE a.app_code='AIDAA' ON CONFLICT (permission_code) DO NOTHING;
INSERT INTO iam.role_permissions (role_id, permission_id) SELECT r.role_id, p.permission_id FROM (VALUES ('AIDAA.ADMIN', ARRAY['audit.library.read','audit.location.read','audit.location.create','audit.location.update','audit.location.delete','audit.costrate.read','audit.costrate.create','audit.costrate.update','audit.costrate.delete']),('AIDAA.BOARD', ARRAY['audit.location.read','audit.costrate.read','audit.costrate.approve']),('AIDAA.HEAD_AUDIT', ARRAY['audit.library.read','audit.library.manage','audit.location.read','audit.location.create','audit.location.update','audit.costrate.read']),('AIDAA.AUDITOR', ARRAY['audit.library.read','audit.location.read','audit.costrate.read']),('AIDAA.HR', ARRAY['audit.location.read']),('AIDAA.FINANCE', ARRAY['audit.location.read','audit.costrate.read','audit.costrate.create','audit.costrate.update','audit.costrate.delete']),('AIDAA.GENERAL_AFFAIRS', ARRAY['audit.location.read','audit.costrate.read'])) AS v(rc, pcs) CROSS JOIN LATERAL unnest(v.pcs) AS u(pc) JOIN iam.roles r ON r.role_code = v.rc JOIN iam.permissions p ON p.permission_code = u.pc ON CONFLICT (role_id, permission_id) DO NOTHING;